mkuse!{use crate :: iter :: TrustedLen ;}
mkitem!{mktrait!{# [doc = " [`TrustedLen`] cannot have methods, so this allows augmenting it."] # [doc = ""] # [doc = " It currently requires `TrustedLen` because it's unclear whether it's"] # [doc = " reasonably possible to depend on the `size_hint` of anything else."] pub (crate) trait UncheckedIterator : TrustedLen { # [doc = " Gets the next item from a non-empty iterator."] # [doc = ""] # [doc = " Because there's always a value to return, that means it can return"] # [doc = " the `Item` type directly, without wrapping it in an `Option`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This can only be called if `size_hint().0 != 0`, guaranteeing that"] # [doc = " there's at least one item available."] # [doc = ""] # [doc = " Otherwise (aka when `size_hint().1 == Some(0)`), this is UB."] # [doc = ""] # [doc = " # Note to Implementers"] # [doc = ""] # [doc = " This has a default implementation using [`Option::unwrap_unchecked`]."] # [doc = " That's probably sufficient if your `next` *always* returns `Some`,"] # [doc = " such as for infinite iterators.  In more complicated situations, however,"] # [doc = " sometimes there can still be `insertvalue`/`assume`/`extractvalue`"] # [doc = " instructions remaining in the IR from the `Option` handling, at which"] # [doc = " point you might want to implement this manually instead."] # [unstable (feature = "trusted_len_next_unchecked" , issue = "37572")] # [inline] unsafe fn next_unchecked (& mut self) -> Self :: Item { let opt = self . next () ; unsafe { opt . unwrap_unchecked () } } }}}